#!/usr/bin/env python3
"""The World Today — 24 November 2026, in one image.

Entry for the make.fun bounty 'Sum up 24 November's world news in one image'
(slug: news-image-20261124).

What this program does
----------------------
It writes one 1024x1024 PNG newspaper front page to
$MAKEFUN_OUTPUT_DIR/entry.png (falling back to /output/entry.png, then to the
script's own directory for local runs). The page carries 40 stories that
happened on, or were first reported on, Tuesday 24 November 2026:

  * a masthead with the date and a red date band,
  * THE DAY IN NUMBERS (six figures from the day),
  * three TOP STORIES with small drawn illustrations,
  * a world map with 11 numbered pins and a pin key,
  * ALSO ON — the remaining 37 stories, grouped by region,
  * a DATE CHECK box naming look-alike stories from other dates that were
    deliberately left out, and a sources footer.

How it works
------------
The front page was composed locally (render_24nov.py, Pillow) and is embedded
below as base64 in a single line, so this program needs only the Python
standard library, makes no network calls, and is fully deterministic: run it
twice and both runs write the same bytes. If the embedded data ever failed to
decode, a pure-stdlib fallback draws a minimal title page instead, so the
program still exits 0 within the time limit.

No network. No secrets. Python 3 only, standard library only.

Built 24 Nov 2026 (WIB) from research/stories-23nov.md; the rendered PNG was
packed into IMAGE_B64 above as a single line.
"""

import base64
import os
import struct
import sys
import zlib

# The rendered 1024x1024 front page, base64, one line.
# Replaced by the build step (pack step) with the actual PNG bytes.
IMAGE_B64 = ""

# ---------------------------------------------------------------- fallback
# A tiny 5x7 bitmap font (only the glyphs the fallback message needs).
# Each glyph is 7 rows of 5 bits, written as strings of 0/1.
_FONT = {
    "A": ["01110", "10001", "10001", "11111", "10001", "10001", "10001"],
    "B": ["11110", "10001", "10001", "11110", "10001", "10001", "11110"],
    "D": ["11110", "10001", "10001", "10001", "10001", "10001", "11110"],
    "E": ["11111", "10000", "10000", "11110", "10000", "10000", "11111"],
    "H": ["10001", "10001", "10001", "11111", "10001", "10001", "10001"],
    "L": ["10000", "10000", "10000", "10000", "10000", "10000", "11111"],
    "M": ["10001", "11011", "10101", "10101", "10001", "10001", "10001"],
    "N": ["10001", "11001", "10101", "10011", "10001", "10001", "10001"],
    "O": ["01110", "10001", "10001", "10001", "10001", "10001", "01110"],
    "R": ["11110", "10001", "10001", "11110", "10100", "10010", "10001"],
    "T": ["11111", "00100", "00100", "00100", "00100", "00100", "00100"],
    "V": ["10001", "10001", "10001", "10001", "10001", "01010", "00100"],
    "W": ["10001", "10001", "10001", "10101", "10101", "11011", "10001"],
    "Y": ["10001", "10001", "01010", "00100", "00100", "00100", "00100"],
    "0": ["01110", "10001", "10011", "10101", "11001", "10001", "01110"],
    "2": ["01110", "10001", "00001", "00110", "01000", "10000", "11111"],
    "3": ["11111", "00010", "00100", "00010", "00001", "10001", "01110"],
    "6": ["00110", "01000", "10000", "11110", "10001", "10001", "01110"],
    " ": ["00000", "00000", "00000", "00000", "00000", "00000", "00000"],
    "-": ["00000", "00000", "00000", "01110", "00000", "00000", "00000"],
}


def _fallback_png():
    """Build a minimal 1024x1024 PNG (paper background + title text)."""
    w, h = 1024, 1024
    paper = (251, 248, 241)
    ink = (17, 17, 17)
    red = (185, 28, 28)
    rows = []
    for _y in range(h):
        rows.append(bytearray(paper * w))
    # red band near the top
    for y in range(100, 130):
        for x in range(24, 1000):
            rows[y][x * 3:x * 3 + 3] = bytes(red)

    def put_text(text, x0, y0, scale, color):
        for ci, ch in enumerate(text):
            glyph = _FONT.get(ch, _FONT[" "])
            for gy in range(7):
                for gx in range(5):
                    if glyph[gy][gx] == "1":
                        for sy in range(scale):
                            for sx in range(scale):
                                px = x0 + (ci * 6 + gx) * scale + sx
                                py = y0 + gy * scale + sy
                                if 0 <= px < w and 0 <= py < h:
                                    rows[py][px * 3:px * 3 + 3] = bytes(color)

    put_text("THE WORLD TODAY", 200, 30, 6, ink)
    put_text("TUESDAY 24 NOVEMBER 2026", 260, 160, 4, ink)
    put_text("ONE IMAGE - ONE DAY", 330, 220, 4, red)

    raw = b"".join(b"\x00" + bytes(row) for row in rows)
    comp = zlib.compress(raw, 6)

    def chunk(kind, data):
        out = struct.pack(">I", len(data)) + kind + data
        return out + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)

    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    return png


# ---------------------------------------------------------------- main
def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError:
        out_dir = os.path.dirname(os.path.abspath(__file__))
    out_path = os.path.join(out_dir, "entry.png")
    data = None
    try:
        data = base64.b64decode(IMAGE_B64, validate=True)
        if not data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise ValueError("embedded data is not a PNG")
    except Exception:
        data = _fallback_png()
    with open(out_path, "wb") as fh:
        fh.write(data)
    return 0


if __name__ == "__main__":
    sys.exit(main())
